parameters.jsCode:
const res = $input.first().json;
let parsed = {};

try {
  if (res.candidates?.[0]?.content?.parts?.[0]?.text) {
    // Gemini response parsing
    const geminiText = res.candidates[0].content.parts[0].text;
    parsed = JSON.parse(geminiText);
  } else if (res.choices?.[0]?.message?.content) {
    // OpenAI response parsing
    const openaiText = res.choices[0].message.content;
    parsed = JSON.parse(openaiText);
  } else {
    parsed = res;
  }
} catch (e) {
  parsed = {
    intent: 'general',
    category: 'personal',
    language: 'English',
    priority: 'normal',
    should_reply: true,
    requires_approval: true,
    reply_text: 'Thank you for reaching out. I have received your message and will review it shortly.',
    reason: 'JSON parsing fallback.'
  };
}

return [{
  json: parsed
}];
